```typescript
/**
 * Neonatal Hyperbilirubinemia Clinical Compass™
 * Logic Engine — AAP Clinical Practice Guideline 2022 (updated 2025)
 *
 * References:
 * 1. Kemper AR et al. Clinical Practice Guideline Revision: Management of
 *    Hyperbilirubinemia in the Newborn Infant 35 or More Weeks of Gestation.
 *    Pediatrics. 2022;150(3):e2022058859.
 * 2. AAP Neonatal Jaundice Phototherapy Nomogram 2022.
 * 3. Bhutani VK et al. Predischarge Bilirubin Nomogram. Pediatrics. 1999.
 */

export type GestationalAgeCategory =
  | "35_36_weeks"
  | "37_38_weeks"
  | "39_plus_weeks";

export type NeurotoxicityRiskLevel =
  | "lower"   // ≥38 weeks + no risk factors
  | "medium"  // 35–37 weeks OR ≥38 weeks + risk factors
  | "higher"; // 35–37 weeks + risk factors

export interface NeonatalHyperbilirubinemiaInput {
  gestationalAgeWeeks: number;
  gestationalAgeCategory: GestationalAgeCategory;
  ageHours: number; // postnatal age in hours
  totalSerumBilirubin: number; // mg/dL
  directBilirubin: number; // mg/dL (conjugated)
  // Risk factors for neurotoxicity
  hasIsoimmunization: boolean; // ABO, Rh incompatibility
  hasG6PDDeficiency: boolean;
  hasAlbuminLow: boolean; // albumin < 3.0 g/dL
  hasSepsis: boolean;
  hasAcidosis: boolean;
  hasAsphyxia: boolean;
  isBreastfeedingOnly: boolean;
  hasWeightLoss: boolean; // >8–10% birth weight
  isEastAsianDescent: boolean;
  // Current clinical status
  hasAcuteBiliaryEncephalopathy: boolean; // hypertonia, retrocollis, opisthotonus
  hasKernicterus: boolean; // chronic bilirubin encephalopathy
  predischargeBilirubinZone: "low" | "low_intermediate" | "high_intermediate" | "high" | null;
  // Treatment context
  currentlyOnPhototherapy: boolean;
  hoursOnPhototherapy: number;
  bilirubinTrendRising: boolean; // rising despite phototherapy
}

export interface NeonatalHyperbilirubinemiaRecommendation {
  primaryRecommendation: string;
  neurotoxicityRisk: NeurotoxicityRiskLevel;
  phototherapyThreshold: number; // mg/dL
  exchangeTransfusionThreshold: number; // mg/dL
  treatmentDecision: "observe" | "enhance_feeding" | "phototherapy" | "intensive_phototherapy" | "exchange_transfusion";
  phototherapyGuidance: string;
  exchangeTransfusionGuidance: string;
  feedingGuidance: string;
  followUpBilirubin: string;
  urgentFlags: string[];
  dischargeReadiness: string;
  evidenceLevel: "A" | "B" | "C";
  rationale: string;
  references: Array<{ citation: string; url: string }>;
}

export function assessNeonatalHyperbilirubinemia(
  input: NeonatalHyperbilirubinemiaInput
): NeonatalHyperbilirubinemiaRecommendation {
  const urgentFlags: string[] = [];

  // ─── Determine neurotoxicity risk level ──────────────────────────────────
  const hasNeurotoxicityRiskFactors =
    input.hasIsoimmunization ||
    input.hasG6PDDeficiency ||
    input.hasAlbuminLow ||
    input.hasSepsis ||
    input.hasAcidosis ||
    input.hasAsphyxia;

  let neurotoxicityRisk: NeurotoxicityRiskLevel;
  if (input.gestationalAgeWeeks >= 38 && !hasNeurotoxicityRiskFactors) {
    neurotoxicityRisk = "lower";
  } else if (input.gestationalAgeWeeks < 37 && hasNeurotoxicityRiskFactors) {
    neurotoxicityRisk = "higher";
  } else {
    neurotoxicityRisk = "medium";
  }

  // ─── Acute bilirubin encephalopathy / kernicterus ────────────────────────
  if (input.hasAcuteBiliaryEncephalopathy || input.hasKernicterus) {
    urgentFlags.push("ACUTE BILIRUBIN ENCEPHALOPATHY / KERNICTERUS: EMERGENCY exchange transfusion. Intensive phototherapy as bridge. Neurology consult. NICU admission.");
    return {
      primaryRecommendation: "EMERGENCY: Acute bilirubin encephalopathy — IMMEDIATE exchange transfusion. Intensive phototherapy as bridge. NICU admission.",
      neurotoxicityRisk,
      phototherapyThreshold: 0,
      exchangeTransfusionThreshold: 0,
      treatmentDecision: "exchange_transfusion",
      phototherapyGuidance: "Intensive phototherapy as bridge to exchange transfusion. Maximize skin surface area exposure.",
      exchangeTransfusionGuidance: "EMERGENCY double-volume exchange transfusion. Use O-negative blood if type-specific not available. NICU required.",
      feedingGuidance: "Continue breastfeeding/feeding during phototherapy. IV fluids if unable to feed.",
      followUpBilirubin: "Bilirubin every 2–4 hours during exchange transfusion.",
      urgentFlags,
      dischargeReadiness: "NOT ready for discharge. NICU admission required.",
      evidenceLevel: "A",
      rationale: `Acute bilirubin encephalopathy present. TSB ${input.totalSerumBilirubin} mg/dL at ${input.ageHours} hours. Emergency exchange transfusion indicated.`,
      references: [
        { citation: "Kemper AR et al. Clinical Practice Guideline Revision: Management of Hyperbilirubinemia in the Newborn Infant 35 or More Weeks of Gestation. Pediatrics. 2022;150(3):e2022058859.", url: "https://publications.aap.org/pediatrics/article/150/3/e2022058859" },
      ],
    };
  }

  // ─── Conjugated hyperbilirubinemia ───────────────────────────────────────
  if (input.directBilirubin > 1.0 || (input.directBilirubin / input.totalSerumBilirubin > 0.2 && input.totalSerumBilirubin > 5)) {
    urgentFlags.push(`CONJUGATED HYPERBILIRUBINEMIA (direct bilirubin ${input.directBilirubin} mg/dL): Evaluate for biliary atresia, Alagille syndrome, metabolic disease. Urgent hepatology/GI referral. Phototherapy NOT effective for conjugated jaundice.`);
  }

  // ─── AAP 2022 phototherapy thresholds (hour-specific nomogram) ───────────
  // Simplified thresholds based on neurotoxicity risk and age
  let phototherapyThreshold: number;
  let exchangeThreshold: number;

  const ageHours = input.ageHours;

  if (neurotoxicityRisk === "lower") {
    // ≥38 weeks, no risk factors
    if (ageHours <= 24) { phototherapyThreshold = 8; exchangeThreshold = 19; }
    else if (ageHours <= 48) { phototherapyThreshold = 13; exchangeThreshold = 22; }
    else if (ageHours <= 72) { phototherapyThreshold = 15; exchangeThreshold = 24; }
    else if (ageHours <= 96) { phototherapyThreshold = 17; exchangeThreshold = 25; }
    else { phototherapyThreshold = 17; exchangeThreshold = 25; }
  } else if (neurotoxicityRisk === "medium") {
    // 35–37 weeks OR ≥38 weeks + risk factors
    if (ageHours <= 24) { phototherapyThreshold = 6; exchangeThreshold = 17; }
    else if (ageHours <= 48) { phototherapyThreshold = 10; exchangeThreshold = 20; }
    else if (ageHours <= 72) { phototherapyThreshold = 13; exchangeThreshold = 22; }
    else if (ageHours <= 96) { phototherapyThreshold = 15; exchangeThreshold = 23; }
    else { phototherapyThreshold = 15; exchangeThreshold = 23; }
  } else {
    // Higher risk: 35–37 weeks + risk factors
    if (ageHours <= 24) { phototherapyThreshold = 5; exchangeThreshold = 15; }
    else if (ageHours <= 48) { phototherapyThreshold = 8; exchangeThreshold = 18; }
    else if (ageHours <= 72) { phototherapyThreshold = 11; exchangeThreshold = 20; }
    else if (ageHours <= 96) { phototherapyThreshold = 13; exchangeThreshold = 21; }
    else { phototherapyThreshold = 13; exchangeThreshold = 21; }
  }

  // ─── Treatment decision ───────────────────────────────────────────────────
  let treatmentDecision: NeonatalHyperbilirubinemiaRecommendation["treatmentDecision"];
  let phototherapyGuidance: string;
  let exchangeGuidance: string;

  const tsb = input.totalSerumBilirubin;

  if (tsb >= exchangeThreshold) {
    treatmentDecision = "exchange_transfusion";
    urgentFlags.push(`TSB ${tsb} mg/dL ≥ EXCHANGE TRANSFUSION THRESHOLD (${exchangeThreshold} mg/dL): Prepare for double-volume exchange transfusion. Intensive phototherapy as bridge. NICU admission.`);
    phototherapyGuidance = "Intensive phototherapy as bridge to exchange transfusion. Maximize skin exposure. Continuous monitoring.";
    exchangeGuidance = `EXCHANGE TRANSFUSION INDICATED: TSB ${tsb} mg/dL ≥ threshold ${exchangeThreshold} mg/dL. Double-volume exchange (160–200 mL/kg). Use irradiated, CMV-negative blood. NICU required. Repeat bilirubin 2–4 hours post-exchange.`;
  } else if (tsb >= phototherapyThreshold + 2 && input.currentlyOnPhototherapy && input.bilirubinTrendRising) {
    treatmentDecision = "intensive_phototherapy";
    urgentFlags.push(`TSB RISING DESPITE PHOTOTHERAPY: ${tsb} mg/dL. Consider intensive phototherapy (multiple lights, fiber-optic blanket). Reassess for exchange transfusion if not responding within 4–6 hours.`);
    phototherapyGuidance = "INTENSIVE PHOTOTHERAPY: Multiple phototherapy lights + fiber-optic blanket. Maximize skin surface area. Bilirubin every 2–4 hours. Discontinue phototherapy only when TSB ≥2 mg/dL below threshold.";
    exchangeGuidance = `Exchange transfusion threshold: ${exchangeThreshold} mg/dL. Current TSB ${tsb} mg/dL. Monitor closely — exchange if rising toward threshold.`;
  } else if (tsb >= phototherapyThreshold) {
    treatmentDecision = "phototherapy";
    phototherapyGuidance = `PHOTOTHERAPY INDICATED: TSB ${tsb} mg/dL ≥ threshold ${phototherapyThreshold} mg/dL. Standard phototherapy (irradiance ≥30 μW/cm²/nm). Recheck bilirubin in 4–6 hours initially, then every 6–12 hours. Discontinue when TSB ≥2 mg/dL below threshold.`;
    exchangeGuidance = `Exchange transfusion threshold: ${exchangeThreshold} mg/dL. Current TSB ${tsb} mg/dL — ${(exchangeThreshold - tsb).toFixed(1)} mg/dL below threshold.`;
  } else if (tsb >= phototherapyThreshold - 2) {
    treatmentDecision = "enhance_feeding";
    phototherapyGuidance = `TSB ${tsb} mg/dL — within 2 mg/dL of phototherapy threshold (${phototherapyThreshold} mg/dL). Enhance feeding, monitor closely. Recheck bilirubin in 4–6 hours.`;
    exchangeGuidance = `Exchange transfusion threshold: ${exchangeThreshold} mg/dL. Not currently indicated.`;
  } else {
    treatmentDecision = "observe";
    phototherapyGuidance = `TSB ${tsb} mg/dL — below phototherapy threshold (${phototherapyThreshold} mg/dL). Observe. Ensure adequate feeding. Follow-up bilirubin per predischarge nomogram zone.`;
    exchangeGuidance = "Exchange transfusion not indicated.";
  }

  // ─── Feeding guidance ────────────────────────────────────────────────────
  let feedingGuidance: string;
  if (input.isBreastfeedingOnly && input.hasWeightLoss) {
    feedingGuidance = "BREASTFEEDING JAUNDICE: Increase breastfeeding frequency to ≥8–12 times/day. Lactation consultant referral. Supplement with expressed breast milk or formula if weight loss >10% or inadequate milk supply. Do NOT routinely discontinue breastfeeding.";
  } else {
    feedingGuidance = "Ensure adequate feeding (≥8–12 feeds/day for breastfed infants). IV hydration only if severely dehydrated or unable to feed. Supplementation with formula acceptable if weight loss >10%.";
  }

  // ─── Follow-up bilirubin ─────────────────────────────────────────────────
  let followUpBilirubin: string;
  if (treatmentDecision === "exchange_transfusion" || treatmentDecision === "intensive_phototherapy") {
    followUpBilirubin = "Bilirubin every 2–4 hours during treatment. Rebound bilirubin 24 hours after phototherapy discontinuation.";
  } else if (treatmentDecision === "phototherapy") {
    followUpBilirubin = "Recheck bilirubin in 4–6 hours initially, then every 6–12 hours. Rebound bilirubin 24 hours after phototherapy discontinuation.";
  } else {
    followUpBilirubin = "Follow-up bilirubin based on predischarge nomogram zone and risk factors. High-intermediate or high zone: recheck within 24 hours of discharge.";
  }

  // ─── Discharge readiness ─────────────────────────────────────────────────
  let dischargeReadiness: string;
  if (treatmentDecision === "observe" || treatmentDecision === "enhance_feeding") {
    dischargeReadiness = `Discharge may be appropriate if TSB in low or low-intermediate zone, adequate feeding, and reliable follow-up arranged. Follow-up bilirubin within 24–48 hours of discharge if in high-intermediate zone.`;
  } else {
    dischargeReadiness = "NOT ready for discharge. Continue treatment and monitoring.";
  }

  const primaryRec = urgentFlags.length > 0
    ? urgentFlags[0]
    : `NEONATAL JAUNDICE — TSB ${tsb} mg/dL at ${ageHours} hours. ${input.gestationalAgeWeeks} weeks GA. Risk: ${neurotoxicityRisk}. Phototherapy threshold: ${phototherapyThreshold} mg/dL. Decision: ${treatmentDecision.replace(/_/g, " ").toUpperCase()}.`;

  return {
    primaryRecommendation: primaryRec,
    neurotoxicityRisk,
    phototherapyThreshold,
    exchangeTransfusionThreshold: exchangeThreshold,
    treatmentDecision,
    phototherapyGuidance,
    exchangeTransfusionGuidance: exchangeGuidance,
    feedingGuidance,
    followUpBilirubin,
    urgentFlags,
    dischargeReadiness,
    evidenceLevel: "A",
    rationale: `TSB ${tsb} mg/dL at ${ageHours} hours. GA ${input.gestationalAgeWeeks} weeks. Neurotoxicity risk: ${neurotoxicityRisk}. Risk factors: isoimmunization=${input.hasIsoimmunization}, G6PD=${input.hasG6PDDeficiency}, sepsis=${input.hasSepsis}. Per AAP 2022 CPG.`,
    references: [
      { citation: "Kemper AR et al. Clinical Practice Guideline Revision: Management of Hyperbilirubinemia in the Newborn Infant 35 or More Weeks of Gestation. Pediatrics. 2022;150(3):e2022058859.", url: "https://publications.aap.org/pediatrics/article/150/3/e2022058859" },
      { citation: "Bhutani VK et al. Predischarge Bilirubin Nomogram for Identifying Neonates at Risk. Pediatrics. 1999;103(1):6–14.", url: "https://publications.aap.org/pediatrics/article/103/1/6/63498" },
    ],
  };
}
